_GATE = {'before_bytes': 4368, 'before_sha256': '426100c4f31e825c9e0f0c556c8c89d23aa45a40593978cb5fd8d5946a4beeb8', 'after_bytes': 5544, 'after_sha256': '2abe6a4074be6c75514755c741d10792e78e80d914e7ae063e1f43ce470d0992', 'inverse': (('    /** Explicit classified pair over two REAL keys. The caller must have compared complete values.\n     * This timing helper grants no action or graph authority and never substitutes a digest. */\n    Result sampleClassifiedPair(long now,FrameKey expectedPrevious,long expectedAt,FrameKey actual,boolean allowed){\n        if(retired||!allowed)return Result.CANCELLED;\n        if(!requestAlive(now,true)||now>=settleDeadline)return Result.EXPIRED;\n        boolean sameWindow=expectedPrevious!=null&&actual!=null&&!expectedPrevious.truncated&&!actual.truncated\n                &&expectedPrevious.packageName.equals(actual.packageName)&&expectedPrevious.windowId==actual.windowId\n                &&expectedPrevious.rotation==actual.rotation&&expectedPrevious.left==actual.left&&expectedPrevious.top==actual.top\n                &&expectedPrevious.right==actual.right&&expectedPrevious.bottom==actual.bottom;\n        if(sameWindow&&previous!=null&&previous.equals(expectedPrevious)&&previousAt==expectedAt\n                &&now>=expectedAt&&now-expectedAt>=SAMPLE_GAP_MS){\n            previous=actual;previousAt=now;return Result.READY;\n        }\n        return Result.WAIT;\n    }\n', ''),)}

def _digest(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()

def _restore(value, record):
    if type(value) is not str:
        raise ValueError("exact reviewed UTF-8 method text required")
    if len(value.encode("utf-8")) != record["after_bytes"] or _digest(value) != record["after_sha256"]:
        raise ValueError("unreviewed complete sampling body or Gate")
    proof = value
    for revised, prior in record["inverse"]:
        if proof.count(revised) != 1:
            raise ValueError("unique complete sampling inverse block required")
        proof = proof.replace(revised, prior, 1)
    if len(proof.encode("utf-8")) != record["before_bytes"] or _digest(proof) != record["before_sha256"]:
        raise ValueError("complete 0a8 sampling predecessor required")
    return proof

def body_predecessor(anchor, value, implementation=None):
    """Keep the old guarded route or undo one exact new route on a proof copy."""
    if type(value) is not str:
        raise ValueError("exact reviewed method text required")
    record = _BODIES.get(anchor)
    if record is None:
        return value, False
    if len(value.encode("utf-8")) == record["before_bytes"] and _digest(value) == record["before_sha256"]:
        if implementation is not None:
            raise ValueError("legacy body must not hide a new sampling implementation")
        return value, False
    if anchor == ACCEPT_ANCHOR:
        if len(value.encode("utf-8")) != ACCEPT_WRAPPER_BYTES or _digest(value) != ACCEPT_WRAPPER_SHA256:
            raise ValueError("exact null-forwarding compatibility wrapper required")
        # Proof copy only; compile the current complete Service implementation.
        if type(implementation) is str and _digest(implementation) == 'ab4241d46100fcaf8ccacfa274d792d6244f5cd1e5269a37ad6e3e90bf08e94c':
            if len(implementation.encode('utf-8')) != 9103:
                raise ValueError('exact current-sample refusal body length required')
            revised, prior = ('                request.ctripSamplingProof=null;\n                boolean initialFormCurrent=formCurrent;\n                formCurrent=formCurrent&&formRead.after.epoch==request.ctripFormSampleEpoch\n                        &&request.ctripFormSample==formRead.before\n                        &&sameObservationWatermark(formRead.after.completed,request.eventWatermark());\n                if(!formCurrent){\n                    if(formRead!=null)recordCtripSampleRefusal(request,formRead,initialFormCurrent);\n                    request.clearCtripSample("SAMPLE_CANDIDATE_NOT_CURRENT");\n                }\n', '                request.ctripSamplingProof=null;\n                formCurrent=formCurrent&&formRead.after.epoch==request.ctripFormSampleEpoch\n                        &&request.ctripFormSample==formRead.before\n                        &&sameObservationWatermark(formRead.after.completed,request.eventWatermark());\n                if(!formCurrent)request.clearCtripSample("SAMPLE_CANDIDATE_NOT_CURRENT");\n')
            if implementation.count(revised) != 1:
                raise ValueError('unique complete current-sample refusal body inverse required')
            implementation = implementation.replace(revised, prior, 1)
            if len(implementation.encode('utf-8')) != 8906 or _digest(implementation) != '202eab36242779bde2456127f364162755442e8c50ad0ec6fe15942e760581d1':
                raise ValueError('complete d4 dual-clock accept predecessor required')
        return _restore(implementation, record), True
    return _restore(value, record), True

def gate_predecessor(value):
    if type(value) is not bytes:
        raise ValueError("exact Gate bytes required")
    text = value.decode("utf-8")
    if len(value) == _GATE["before_bytes"] and _digest(text) == _GATE["before_sha256"]:
        return value, False
    return _restore(text, _GATE).encode("utf-8"), True
